"use client";

import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { departamentsApi, Envelope } from "@/entities/departaments/api";
import { DepartamentChild, DepartamenthAndChildDto } from "@/entities/departaments/types";

const PAGE_SIZE = 5;

function getPagerPages(current: number, last: number): Array<number | string> {
  const pages: Array<number | string> = [];

  for (let i = 1; i <= last; i += 1) {
    if (last <= 5 || i === 1 || i === last || Math.abs(i - current) <= 1) {
      pages.push(i);
    } else if (i === 2 || i === last - 1) {
      pages.push("...");
    }
  }

  return pages.filter((page, index) => page !== "..." || pages[index - 1] !== "...");
}

export default function DepartamentsPage() {
  const [page, setPage] = useState(1);

  const { data, isLoading, error } = useQuery(
    ["departaments-roots", page],
    () =>
      departamentsApi.getDepartaments({
        page,
        pageSize: PAGE_SIZE,
        prefetch: 3,
      }),
    {
      keepPreviousData: true,
      staleTime: 1000 * 60,
    }
  );

  const models: DepartamentChild[] = data?.result?.departamenthAndChildModels ?? [];
  const total = data?.result?.totalCount ?? 0;
  const lastPage = Math.max(1, Math.ceil(total / PAGE_SIZE));
  const pagerPages = getPagerPages(page, lastPage);

  return (
    <div className="bg-background text-foreground min-h-screen p-4 sm:p-6 md:p-8">
      <div className="mx-auto max-w-6xl space-y-4">
        <section className="rounded-2xl border border-border bg-card p-4 sm:p-5">
          <div className="flex flex-col gap-2 sm:flex-row sm:items-end sm:justify-between">
            <div>
              <p className="text-xs uppercase tracking-[0.25em] text-muted-foreground">Locations / Departments</p>
              <h1 className="mt-1 text-2xl font-bold sm:text-3xl">Departments</h1>
              <p className="mt-1 max-w-3xl text-sm text-muted-foreground sm:text-base">
                Root departments list. Showing up to 5 items per page.
              </p>
            </div>
            <div className="rounded-xl border border-border bg-muted px-3 py-2 text-xs font-medium text-foreground">Total: {total}</div>
          </div>

          <div className="mt-3 flex flex-wrap items-center gap-2">
            <button
              type="button"
              className="rounded-md border border-border bg-muted px-3 py-1.5 text-xs font-semibold text-foreground transition hover:border-primary hover:text-primary disabled:opacity-50 disabled:cursor-not-allowed"
              onClick={() => setPage((prev) => Math.max(1, prev - 1))}
              disabled={page <= 1 || isLoading}
            >
              ← Prev
            </button>

            {pagerPages.map((item, index) =>
              item === "..." ? (
                <span key={`dots-${index}`} className="px-2 text-xs text-muted-foreground">
                  ...
                </span>
              ) : (
                <button
                  key={`page-${item}`}
                  type="button"
                  onClick={() => setPage(Number(item))}
                  disabled={isLoading}
                  className={`rounded-md border px-2 py-1 text-xs font-semibold ${
                    item === page
                      ? "border-primary bg-primary text-white"
                      : "border-border bg-background text-foreground hover:border-primary"
                  }`}
                >
                  {item}
                </button>
              )
            )}

            <button
              type="button"
              className="rounded-md border border-border bg-muted px-3 py-1.5 text-xs font-semibold text-foreground transition hover:border-primary hover:text-primary disabled:opacity-50 disabled:cursor-not-allowed"
              onClick={() => setPage((prev) => Math.min(lastPage, prev + 1))}
              disabled={page >= lastPage || isLoading}
            >
              Next →
            </button>

            <span className="ml-auto text-xs text-muted-foreground">Page {page} of {lastPage}</span>
          </div>
        </section>

        {isLoading ? (
          <div className="rounded-2xl border border-border bg-card p-4 text-center text-muted-foreground">Loading...</div>
        ) : error ? (
          <div className="rounded-2xl border border-destructive/40 bg-destructive/10 p-4 text-center text-destructive">Error loading departments. Please refresh.</div>
        ) : models.length === 0 ? (
          <div className="rounded-2xl border border-border bg-card p-4 text-center text-muted-foreground">No departments found.</div>
        ) : (
          <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">
            {models.map((item) => (
              <article
                key={item.id}
                className="flex min-h-[200px] flex-col justify-between rounded-2xl border border-border bg-card p-3 sm:p-4 transition hover:-translate-y-0.5 hover:shadow-md"
              >
                <div className="space-y-2">
                  <div className="flex flex-wrap items-start justify-between gap-2">
                    <div className="min-w-0">
                      <h2 className="text-base font-semibold sm:text-lg truncate">{item.name}</h2>
                      <p className="mt-0.5 text-xs text-muted-foreground sm:text-sm truncate">{item.identifier} · {item.path}</p>
                    </div>
                    <span className={`rounded-full px-2 py-0.5 text-[10px] font-semibold sm:text-xs ${item.isActive ? "bg-emerald-500/10 text-emerald-600" : "bg-red-500/10 text-red-600"}`}>
                      {item.isActive ? "Active" : "Inactive"}
                    </span>
                  </div>

                  <div className="grid gap-2 text-xs text-muted-foreground sm:grid-cols-2 sm:text-sm">
                    <div className="rounded-md bg-muted/60 p-2"><span className="font-medium text-foreground">Depth:</span> {item.depth}</div>
                    <div className="rounded-md bg-muted/60 p-2"><span className="font-medium text-foreground">Parent:</span> {item.parentId ?? "—"}</div>
                    <div className="rounded-md bg-muted/60 p-2"><span className="font-medium text-foreground">Children:</span> {item.childs?.length ?? 0}</div>
                    <div className="rounded-md bg-muted/60 p-2"><span className="font-medium text-foreground">More:</span> {item.hasMoreChildren ? "Yes" : "No"}</div>
                  </div>
                </div>

                <div className="mt-2 rounded-xl border border-border p-2 text-xs text-muted-foreground sm:text-sm">
                  {item.childs && item.childs.length > 0 ? (
                    <>
                      <div className="font-medium text-foreground">Child departments:</div>
                      <ul className="ml-3 mt-1 list-disc space-y-1">
                        {item.childs.slice(0, 3).map((child) => (
                          <li key={child.id} className="truncate">{child.name}</li>
                        ))}
                        {item.childs.length > 3 ? <li>+{item.childs.length - 3} more...</li> : null}
                      </ul>
                    </>
                  ) : (
                    <div>No child departments</div>
                  )}
                </div>
              </article>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
